   917  static cdf_property_info_t *
   918  cdf_grow_info(cdf_property_info_t **info, size_t *maxcount, size_t incr)
   919  {
   920          cdf_property_info_t *inp;
   921          size_t newcount = *maxcount + incr;
   922
   923          if (newcount > CDF_PROP_LIMIT) {
   924                  DPRINTF(("exceeded property limit %" SIZE_T_FORMAT "u > %"
   925                      SIZE_T_FORMAT "u\n", newcount, CDF_PROP_LIMIT));
   926                  goto out;
   927          }
   928          inp = CAST(cdf_property_info_t *,
   929              CDF_REALLOC(*info, newcount * sizeof(*inp)));
   930          if (inp == NULL)
   931                  goto out;
   932
   933          *info = inp;
   934          *maxcount = newcount;
   935          return inp;
   936  out:
   937          free(*info);
   938          *maxcount = 0;
   939          *info = NULL;
   940          return NULL;
   941  }
