   943  static int
   944  cdf_copy_info(cdf_property_info_t *inp, const void *p, const void *e,
   945      size_t len)
   946  {
   947          if (inp->pi_type & CDF_VECTOR)
   948                  return 0;
   949
   950          if (CAST(size_t, CAST(const char *, e) - CAST(const char *, p)) < len)
   951                  return 0;
   952
   953          (void)memcpy(&inp->pi_val, p, len);
   954
   955          switch (len) {
   956          case 2:
   957                  inp->pi_u16 = CDF_TOLE2(inp->pi_u16);
   958                  break;
   959          case 4:
   960                  inp->pi_u32 = CDF_TOLE4(inp->pi_u32);
   961                  break;
   962          case 8:
   963                  inp->pi_u64 = CDF_TOLE8(inp->pi_u64);
   964                  break;
   965          default:
   966                  abort();
   967          }
   968          return 1;
   969  }
